import{H as e,V as t,et as n,j as r}from"./chunks/framework.BY5yoHkb.js";import"./chunks/assets.DbXR9L7q.js";var i=JSON.parse(`{"title":"拜年祭众筹正式开始","description":"","frontmatter":{"title":"拜年祭众筹正式开始","date":"2026-10-04T00:00:00.000Z","rss":true,"category":"announcements","hidden":false},"headers":[],"relativePath":"posts/announcements/拜年祭众筹正式开始.md","filePath":"posts/announcements/拜年祭众筹正式开始.md"}`),a={name:`posts/announcements/拜年祭众筹正式开始.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p><img src="/img/%E9%87%8D%E8%BF%94%E6%9C%AA%E6%9D%A5%EF%BC%9A1999%E4%B8%89%E5%91%A8%E5%B9%B4ARG%E8%A7%A3%E8%B0%9C%E6%B4%BB%E5%8A%A8%E7%BC%A9%E7%95%A5/%E6%8B%9C%E5%B9%B4%E7%A5%AD_%E6%A8%AA%E7%89%88_%E4%B8%AD%E8%8B%B1%E6%96%87%E5%B0%8F%E5%AD%97%E6%A0%A1%E6%AD%A3.png" alt="拜年祭准备正式开始！" width="1672" height="941"></p><p>大家好，打扰啦！我们正在筹备迷雾论坛第一届新春会，预计于2027年1月举办，现在向大家说明两件事：</p><h2 id="一、征稿启事" tabindex="-1">一、征稿启事 <a class="header-anchor" href="#一、征稿启事" aria-label="Permalink to “一、征稿启事”">​</a></h2><p>欢迎大家踊跃投稿！无论是文字、绘画还是视频，任何形式的创作我们都期待你的参与。欢迎一起展示arg社群风采，有意向者可加入群聊：1126012458</p><h2 id="二、众筹说明" tabindex="-1">二、众筹说明 <a class="header-anchor" href="#二、众筹说明" aria-label="Permalink to “二、众筹说明”">​</a></h2><p>为解决部分活动经费，我们发起本次众筹，设三个基础档位：</p><p>🎗 12元档 —— 感谢名单 + 新春会吧唧 ×1（邮费自理） <a href="https://afdian.com/item/aa8a6c7cbf2511f1b91552540025c377" target="_blank" rel="noreferrer">爱发电链接</a></p><p>🔑 19元档 —— 以上全部 + misT钥匙扣 ×1（邮费自理） <a href="https://afdian.com/item/9bc64ba4bf2311f1b0475254001e7c00" target="_blank" rel="noreferrer">爱发电链接</a></p><p>🎁 29元档 —— 完整新春会纪念套组（吧唧 + 钥匙扣 + 闪卡×2，邮费自理） <a href="https://afdian.com/item/dd54ef8abf2311f198285254001e7c00" target="_blank" rel="noreferrer">爱发电链接</a></p><hr><h2 id="另设两个特别档位" tabindex="-1">另设两个特别档位： <a class="header-anchor" href="#另设两个特别档位" aria-label="Permalink to “另设两个特别档位：”">​</a></h2><p>🖊 37元档（限量20份，按付款顺序先到先得） —— 纪念套组 + 新春会staff亲笔签名祝福</p><p>✨ 50元档（限量3份） —— 据说拍下它会有不好的事情发生……但谁知道呢。 （本档存在一定娱乐性质，我们不对礼品是否符合玩家心理期待负责，介意者慎拍）</p><p>众筹预计于2026年12月15日截止，纪念套组预计于新春会前后发货，制作进度将在群内同步更新。</p><p>本次活动的全部收益都将用于支持迷雾论坛新春会，结束后将公开全部收入用途，感谢各位的理解与支持！在众筹过程中，你也可以前往空白解谜组看到历史收入记录（爱发电有6%的抽成）</p><hr><p><strong>我们倡导适度消费，未成年人请在监护人知情同意后购买</strong><strong>邮费以通常情况计，考虑到散发比集发贵一点，我们现在按照散发标注邮费，而如有富余邮费单独退还较为麻烦，所以将全部用于活动，不足部分另行协商处理</strong><strong>若活动未能办成，将退还全部所受资金。包括：重大不可抗力因素、节目数量不足、筹备资金未达生产成本150%的目标、主创团队出现重大变故，以及其他可能影影响活动完整举办的事件</strong><strong>你也可以选择以充电方式资助（无实体礼物，感谢名单视具体金额而定），心意同样感谢</strong><strong>本活动主办方不对节目提供方造成的损失负责</strong><strong>准备货量为50 组 起，如有多余部分将以售出形式处理</strong> 感谢每一位支持迷雾论坛的朋友，2027年1月，我们新春会见！🎉</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};